"use client";

import { loadFont as loadSans } from "@remotion/google-fonts/InstrumentSans";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import type React from "react";
import { useId } from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_LINES,
  MAX_GREYS,
  type SlopeChartElementId,
  slopeChartTimeline,
} from "./timeline";

const { fontFamily: sans } = loadSans("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const { fontFamily: serif } = loadSerif("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface SlopeLine {
  before: number;
  after: number;
}

export interface SlopeChartProps {
  lines?: SlopeLine[];
  highlight?: SlopeLine;
  value?: string;
  label?: string;
  beforeLabel?: string;
  afterLabel?: string;
  accent?: string;
  /** Text color of the axis headings and the hero stat; overrides the theme. */
  ink?: string;
  background?: string;
  /** Typeface for the labels and values. Load it yourself; Instrument Sans by default. */
  fontFamily?: string;
  /** Frames between grey lines as they draw in. */
  stagger?: number;
  /** Frame the hero line starts to climb; the stat lands with it. */
  climbAt?: number;
  /** Size of the chart, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  grain?: boolean;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the axes, each grey line, the hero line's climb
   * and the stat's landing, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<SlopeChartElementId>;
}

const DEFAULT_HIGHLIGHT: SlopeLine = { before: 6, after: 41 };

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const DRAW_EASE = Easing.bezier(0.45, 0, 0.2, 1);
const CLIMB_EASE = Easing.bezier(0.55, 0, 0.15, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    line: "#9C9BA1",
    axis: "rgba(255,255,255,0.22)",
    tick: "rgba(255,255,255,0.08)",
    // gradients.sh "limb": brightens as the line climbs
    limb: ["accent", "#8a8bff", "#e9ecff"],
    wedge: 0.34,
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    line: "#8F8D87",
    axis: "rgba(18,18,20,0.24)",
    tick: "rgba(18,18,20,0.08)",
    limb: ["#8a8bff", "accent", "#4b2bd6"],
    wedge: 0.18,
    grain: 0.045,
  },
} as const;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function spread(ys: number[], minGap: number) {
  const order = ys.map((y, i) => ({ y, i })).sort((a, b) => a.y - b.y);
  for (let pass = 0; pass < 8; pass++) {
    for (let k = 1; k < order.length; k++) {
      const gap = order[k].y - order[k - 1].y;
      if (gap < minGap) {
        const push = (minGap - gap) / 2;
        order[k - 1].y -= push;
        order[k].y += push;
      }
    }
  }
  const out = [...ys];
  for (const o of order) out[o.i] = o.y;
  return out;
}

function taper(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  w0: number,
  w1: number,
) {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;
  const a = [x0 + (nx * w0) / 2, y0 + (ny * w0) / 2];
  const b = [x1 + (nx * w1) / 2, y1 + (ny * w1) / 2];
  const c = [x1 - (nx * w1) / 2, y1 - (ny * w1) / 2];
  const d = [x0 - (nx * w0) / 2, y0 - (ny * w0) / 2];
  return `M${a[0]} ${a[1]} L${b[0]} ${b[1]} L${c[0]} ${c[1]} L${d[0]} ${d[1]} Z`;
}

const fmt = (n: number) =>
  Number.isInteger(n) ? String(n) : n.toFixed(1).replace(/\.0$/, "");

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function SlopeChart(props: SlopeChartProps) {
  const {
    lines = DEFAULT_LINES,
    highlight = DEFAULT_HIGHLIGHT,
    value = "6.8×",
    label = "more launch videos shipped",
    beforeLabel = "Before",
    afterLabel = "After",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    scale = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    slopeChartTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const axesEl = tl.get("axes");
  const headingsEl = tl.get("headings");
  const climbEl = tl.get("climb");
  const hitEl = tl.get("hit");
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const stage = background ?? p.bg;
  const hole = background && background !== "transparent" ? background : p.bg;
  const climbAt = climbEl.start;
  const hitAt = hitEl.start;

  const greys = lines.slice(0, MAX_GREYS);
  const all = [...greys, highlight];
  const max = Math.max(1, ...all.flatMap((l) => [l.before, l.after]));
  const min = Math.min(0, ...all.flatMap((l) => [l.before, l.after]));

  const xL = W * 0.2;
  const xR = W * 0.58;
  const yTop = H * 0.235;
  const yBot = H * 0.8;
  const yOf = (v: number) => yBot - ((v - min) / (max - min)) * (yBot - yTop);

  const axisIn = interpolate(t, [axesEl.start, axesEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const axisLabelIn = interpolate(
    t,
    [headingsEl.start, headingsEl.end],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  // The chart sits centred alone; the frame eases over as the number lands.
  const camera = (tt: number) => {
    const push = interpolate(tt, [0, hitAt + hitEl.beat("settle")], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
    const slide = interpolate(
      tt,
      [climbAt + climbEl.beat("slideAt"), hitAt + hitEl.beat("slideEnd")],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_IO,
      },
    );
    return { s: 0.975 + 0.025 * push, x: W * 0.11 * (1 - slide) };
  };
  const { s: camScale, x: camX } = camera(t);
  // The camera's scale is weighed by the half width, the furthest any text
  // sits from its centre.
  const camStep = (a: number, b: number) => {
    const p0 = camera(a);
    const p1 = camera(b);
    return Math.abs(p1.x - p0.x) + Math.abs(p1.s - p0.s) * (W / 2) > 1e-3;
  };
  const camMoving = camStep(t - speed, t) || camStep(t, t + speed);

  const climb = interpolate(t, [climbAt, climbEl.end], [0, 1], {
    ...CLAMP,
    easing: CLIMB_EASE,
  });
  const dimAt = climbAt + climbEl.beat("dimAt");
  const dim = interpolate(t, [dimAt, dimAt + climbEl.beat("dim")], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const leftYs = spread(
    all.map((l) => yOf(l.before)),
    20 * u,
  );
  const rightYs = spread(
    greys.map((l) => yOf(l.after)),
    20 * u,
  );

  const hx0 = xL;
  const hy0 = yOf(highlight.before);
  const hx1 = xR;
  const hy1 = yOf(highlight.after);
  const tipX = hx0 + (hx1 - hx0) * climb;
  const tipY = hy0 + (hy1 - hy0) * climb;
  const wStart = 2.2 * u;
  const wTip = (2.2 + 5.4 * climb) * u;
  const startDot = spring({
    frame: t - (climbAt + climbEl.beat("dot")),
    fps,
    config: { damping: 14, stiffness: 180, mass: 0.6 },
  });

  const hit = spring({
    frame: t - hitAt,
    fps,
    config: { damping: 15, stiffness: 170, mass: 0.7 },
  });
  const hitO = interpolate(
    t,
    [hitAt, hitAt + hitEl.beat("fade")],
    [0, 1],
    CLAMP,
  );
  const ring = interpolate(t, [hitAt, hitEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const lab = interpolate(
    t,
    [hitAt + hitEl.beat("labelAt"), hitEl.end],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );

  const valueSize = 156 * u;
  const gradId = `${useId().replace(/[^a-zA-Z0-9_-]/g, "")}-limb`;
  const tipColor = p.limb[p.limb.length - 1];
  const stroke = Math.max(1, u);

  const greyEls: React.ReactNode[] = [];
  const greyDots: React.ReactNode[] = [];
  greys.forEach((l, i) => {
    const e = tl.get(`line:${i}`);
    const start = e.start;
    const prog = interpolate(t, [start, e.end], [0, 1], {
      ...CLAMP,
      easing: DRAW_EASE,
    });
    if (prog <= 0) return;
    const y0 = yOf(l.before);
    const y1 = yOf(l.after);
    const x = xL + (xR - xL) * prog;
    const y = y0 + (y1 - y0) * prog;
    const o = 0.95 - 0.4 * dim;
    greyEls.push(
      <line
        key={`l${i}`}
        x1={xL}
        y1={y0}
        x2={x}
        y2={y}
        stroke={p.line}
        strokeWidth={1.7 * u}
        strokeLinecap="round"
        opacity={o}
      />,
    );
    const a = interpolate(t, [start, start + e.beat("dot")], [0, 1], CLAMP);
    const b = interpolate(t, [e.end - 4, e.end + 4], [0, 1], CLAMP);
    greyDots.push(
      <circle
        key={`a${i}`}
        cx={xL}
        cy={y0}
        r={3.6 * u * (0.6 + 0.4 * a)}
        fill={p.line}
        opacity={a * o}
      />,
      <circle
        key={`b${i}`}
        cx={xR}
        cy={y1}
        r={3.6 * u * (0.6 + 0.4 * b)}
        fill={p.line}
        opacity={b * o}
      />,
    );
  });

  const gridVals = [0.25, 0.5, 0.75, 1].map((k) => min + (max - min) * k);

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `translateX(${camX}px) scale(${camScale})${glide(camMoving)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={W}
            height={H}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            <defs>
              <linearGradient
                id={gradId}
                gradientUnits="userSpaceOnUse"
                x1={hx0}
                y1={hy0}
                x2={hx1}
                y2={hy1}
              >
                {p.limb.map((c, i) => (
                  <stop
                    key={c}
                    offset={i / (p.limb.length - 1)}
                    stopColor={c === "accent" ? accent : c}
                  />
                ))}
              </linearGradient>
              <linearGradient
                id={`${gradId}-w`}
                gradientUnits="userSpaceOnUse"
                x1={0}
                y1={hy1}
                x2={0}
                y2={hy0}
              >
                <stop
                  offset={0}
                  stopColor={p.limb[1] === "accent" ? accent : p.limb[1]}
                  stopOpacity={p.wedge}
                />
                <stop offset={1} stopColor={accent} stopOpacity={0} />
              </linearGradient>
            </defs>
            {gridVals.map((v) => (
              <line
                key={v}
                x1={xL}
                x2={xL + (xR - xL) * axisIn}
                y1={yOf(v)}
                y2={yOf(v)}
                stroke={p.tick}
                strokeWidth={stroke}
                strokeDasharray={`${2 * u} ${6 * u}`}
              />
            ))}
            {[xL, xR].map((x) => (
              <line
                key={x}
                x1={x}
                x2={x}
                y1={yBot + 14 * u}
                y2={yBot + 14 * u - (yBot - yTop + 28 * u) * axisIn}
                stroke={p.axis}
                strokeWidth={stroke}
              />
            ))}
            {climb > 0 && (
              <path
                d={`M${hx0} ${hy0} L${tipX} ${tipY} L${tipX} ${hy0} Z`}
                fill={`url(#${gradId}-w)`}
              />
            )}
            {greyEls}
            {greyDots}
            {climb > 0 && (
              <>
                <path
                  d={taper(hx0, hy0, tipX, tipY, wStart, wTip)}
                  fill={`url(#${gradId})`}
                />
                <circle
                  cx={tipX}
                  cy={tipY}
                  r={wTip / 2}
                  fill={`url(#${gradId})`}
                />
              </>
            )}
            <circle
              cx={hx0}
              cy={hy0}
              r={5 * u * (0.6 + 0.4 * startDot)}
              fill={accent}
              opacity={Math.min(1, startDot * 1.4)}
            />
            {t >= hitAt && (
              <circle
                cx={hx1}
                cy={hy1}
                r={(8 + 34 * ring) * u}
                fill="none"
                stroke={tipColor}
                strokeWidth={1.5 * u}
                opacity={(1 - ring) * 0.7}
              />
            )}
            {climb > 0 && (
              <circle
                cx={tipX}
                cy={tipY}
                r={(6.5 + 2 * hit) * u}
                fill={`url(#${gradId})`}
              />
            )}
            {climb > 0 && (
              <circle cx={tipX} cy={tipY} r={2.4 * u} fill={hole} />
            )}
          </svg>

          {all.map((l, i) => {
            const isHl = i === all.length - 1;
            const start = isHl
              ? climbAt + climbEl.beat("value")
              : tl.get(`line:${i}`).start;
            const a = interpolate(t, [start + 2, start + 14], [0, 1], {
              ...CLAMP,
              easing: EASE_OUT,
            });
            const o = isHl ? 1 : 0.9 - 0.45 * dim;
            return (
              <div
                key={`v${i}`}
                style={{
                  position: "absolute",
                  left: xL - 120 * u - 18 * u,
                  top: leftYs[i] - 10 * u,
                  width: 120 * u,
                  textAlign: "right",
                  fontFamily,
                  fontWeight: isHl ? 500 : 400,
                  fontSize: 16 * u,
                  lineHeight: `${20 * u}px`,
                  color: isHl ? accent : p.muted,
                  fontVariantNumeric: "tabular-nums",
                  opacity: a * o,
                  transform: `translateX(${(1 - a) * 8 * u}px)`,
                }}
              >
                {fmt(l.before)}
              </div>
            );
          })}

          {greys.map((l, i) => {
            const end = tl.get(`line:${i}`).end;
            const a = interpolate(t, [end - 4, end + 10], [0, 1], {
              ...CLAMP,
              easing: EASE_OUT,
            });
            return (
              <div
                key={`r${i}`}
                style={{
                  position: "absolute",
                  left: xR + 18 * u,
                  top: rightYs[i] - 10 * u,
                  fontFamily,
                  fontWeight: 400,
                  fontSize: 16 * u,
                  lineHeight: `${20 * u}px`,
                  color: p.muted,
                  fontVariantNumeric: "tabular-nums",
                  opacity: a * (0.9 - 0.45 * dim),
                  transform: `translateX(${(1 - a) * -8 * u}px)`,
                }}
              >
                {fmt(l.after)}
              </div>
            );
          })}

          {[
            { x: xL, text: beforeLabel },
            { x: xR, text: afterLabel },
          ].map((ax) => (
            <div
              key={ax.text}
              style={{
                position: "absolute",
                left: ax.x - 100 * u,
                width: 200 * u,
                top: yBot + 30 * u,
                textAlign: "center",
                fontFamily,
                fontWeight: 500,
                fontSize: 18 * u,
                letterSpacing: "-0.01em",
                color: fg,
                opacity: axisLabelIn,
                transform: `translateY(${(1 - axisLabelIn) * 8 * u}px)`,
              }}
            >
              {ax.text}
            </div>
          ))}

          <div
            style={{
              position: "absolute",
              left: xR + 44 * u,
              top: hy1 - valueSize * 0.5,
              opacity: hitO,
              transform: `translateX(${(1 - hit) * -18 * u}px)`,
            }}
          >
            <div
              style={{
                fontFamily: serif,
                fontWeight: 400,
                fontSize: valueSize,
                lineHeight: 1,
                letterSpacing: "-0.02em",
                color: fg,
                fontVariantNumeric: "tabular-nums",
                whiteSpace: "nowrap",
              }}
            >
              {value}
            </div>
            <div
              style={{
                marginTop: 10 * u,
                fontFamily,
                fontWeight: 500,
                fontSize: 20 * u,
                letterSpacing: "-0.01em",
                color: p.muted,
                opacity: lab,
                transform: `translateY(${(1 - lab) * 8 * u}px)`,
                whiteSpace: "nowrap",
              }}
            >
              {label}
            </div>
          </div>
        </AbsoluteFill>
      </ScaleLayer>
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The axes drawing in with their headings, the grey lines drawing one after
// another, then the hero line climbing and the stat landing at its tip.
// Frames on the 30 fps scene timeline, after `delay` and `speed`. The ids are
// public: a saved `timing` prop refers to them.

export type SlopeChartElementId =
  | "axes"
  | "headings"
  | `line:${number}`
  | "climb"
  | "hit";

export interface SlopeChartTimingProps {
  lines?: { before: number; after: number }[];
  /** Frames between grey lines as they draw in. */
  stagger?: number;
  /** Frame the hero line starts to climb; the stat lands with it. */
  climbAt?: number;
}

export const DEFAULT_LINES = [
  { before: 14, after: 16 },
  { before: 20, after: 18 },
  { before: 10, after: 13 },
  { before: 24, after: 22 },
  { before: 17, after: 20 },
  { before: 3, after: 5 },
  { before: 28, after: 27 },
];

export const GREY_STAGGER = 4;
export const CLIMB_AT = 60;
/** At most this many grey lines are drawn. */
export const MAX_GREYS = 8;

const AXES = [0, 16] as const;
const HEADINGS = [6, 22] as const;
const GREY_AT = 12;
const GREY_DRAW = 24;
const CLIMB_LEN = 40;
const HIT_AFTER = 38;

// `axes` draw in and `headings` rise under them. `line:<i>` draws grey line
// `i` over its length, `stagger` after the one before it (a chain); its start
// dot pops over `dot`, its values show around its start and end. `climb` is
// the hero line climbing: its start dot springs from `dot` and its left value
// shows from `value` (both before the start), the grey lines dim from `dimAt`
// over `dim`, and the camera starts sliding over at `slideAt`. `hit`
// (following the climb) is the stat landing over its length: it fades in over
// `fade` and the label rises from `labelAt`; the camera's slide ends at
// `slideEnd` and its push at `settle`.
export const slopeChartTimeline = defineTimeline<
  SlopeChartElementId,
  SlopeChartTimingProps
>(({ lines = DEFAULT_LINES, stagger = GREY_STAGGER, climbAt = CLIMB_AT }) => {
  const greys = lines.slice(0, MAX_GREYS);
  const hitAt = climbAt + HIT_AFTER;
  const elements: TimelineElement<SlopeChartElementId>[] = [
    {
      id: "axes",
      lane: "Axes",
      label: "Axes",
      start: AXES[0],
      length: AXES[1] - AXES[0],
    },
    {
      id: "headings",
      lane: "Axes",
      label: "Headings",
      start: HEADINGS[0],
      length: HEADINGS[1] - HEADINGS[0],
    },
  ];
  greys.forEach((l, i) => {
    elements.push({
      id: `line:${i}`,
      lane: "Lines",
      label: `${l.before} → ${l.after}`,
      start: GREY_AT + i * stagger,
      length: GREY_DRAW,
      follows: i > 0 ? `line:${i - 1}` : undefined,
      beats: { dot: 6 },
    });
  });
  elements.push(
    {
      id: "climb",
      lane: "Hero",
      label: "Climb",
      start: climbAt,
      length: CLIMB_LEN,
      beats: { dot: -6, value: -6, dimAt: -2, dim: 22, slideAt: 8 },
    },
    {
      id: "hit",
      lane: "Hero",
      label: "Stat",
      start: hitAt,
      length: 26,
      follows: "climb",
      beats: { fade: 6, labelAt: 8, slideEnd: 14, settle: 30 },
    },
  );
  return elements
    .map((e, k) => ({ e, k }))
    .sort((a, b) => a.e.start - b.e.start || a.k - b.k)
    .map(({ e }) => e);
});
